package org.eclipse.rdf4j.workbench.commands;

import static org.eclipse.rdf4j.model.util.Values.bnode;

import java.io.StringWriter;
import java.math.BigInteger;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

import org.eclipse.rdf4j.common.iteration.Iterations;
import org.eclipse.rdf4j.model.Model;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.LinkedHashModel;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.MalformedQueryException;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.QueryResultHandlerException;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.RepositoryException;
import org.eclipse.rdf4j.repository.config.RepositoryConfig;
import org.eclipse.rdf4j.repository.config.RepositoryConfigException;
import org.eclipse.rdf4j.repository.manager.LocalRepositoryManager;
import org.eclipse.rdf4j.repository.manager.RemoteRepositoryManager;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.rio.Rio;
import org.eclipse.rdf4j.rio.WriterConfig;
import org.eclipse.rdf4j.rio.helpers.BasicWriterSettings;
import org.eclipse.rdf4j.workbench.base.TransformationServlet;
import org.eclipse.rdf4j.workbench.util.TupleResultBuilder;
import org.eclipse.rdf4j.workbench.util.WorkbenchRequest;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import jakarta.servlet.http.HttpServletResponse;

public class SummaryServlet extends TransformationServlet {

	private static final String EFFECTIVE_CONFIG_TURTLE = "config-model-turtle";

	private final BrowseList browseList = new BrowseList();

	private static final Logger LOGGER = LoggerFactory.getLogger(SummaryServlet.class);

	/** How long the Summary page waits for its counts (plan task M13.3), the same as Types and Graphs. */
	static final long COUNT_BUDGET_MILLIS = BrowseList.COUNT_BUDGET_MILLIS;

	private final long countBudgetMillis;

	public SummaryServlet() {
		this(COUNT_BUDGET_MILLIS);
	}

	/** A Summary page that gives its counts the given time instead (tests use a shorter budget). */
	SummaryServlet(long countBudgetMillis) {
		this.countBudgetMillis = countBudgetMillis;
	}

	@Override
	protected void service(WorkbenchRequest req, HttpServletResponse resp) throws Exception {
		TupleResultBuilder builder = getTupleResultBuilder(req, resp, resp.getOutputStream());
		if (BrowseList.countsRequested(req)) {
			counts(builder);
		} else {
			service(builder);
		}
	}

	/**
	 * The repository, at once: its id, title, location and server, without counts. The page asks for them with
	 * {@code counts=true} once it is shown (plan task M13.3).
	 */
	@Override
	public void service(TupleResultBuilder builder)
			throws RepositoryException, QueryEvaluationException, MalformedQueryException, QueryResultHandlerException {
		builder.metadata(EFFECTIVE_CONFIG_TURTLE, getEffectiveConfigTurtle());
		builder.start("id", "description", "location", "server", "size", "contexts");
		builder.link(List.of(INFO));
		builder.result(info.getId(), info.getDescription(), info.getLocation(), getServer(), null, null);
		builder.end();
	}

	/**
	 * The number of statements ({@code size}) and of named graphs ({@code contexts}), counted on their own connection
	 * for at most two seconds. A count that did not finish is empty, and {@code counts-timed-out} is set.
	 */
	private void counts(TupleResultBuilder builder) throws Exception {
		Map<String, Long> counts = new ConcurrentHashMap<>();
		Optional<Boolean> finished = browseList.withinBudget(() -> {
			try (RepositoryConnection connection = repository.getConnection()) {
				BrowseList.keep(counts, "size", connection.size());
				BrowseList.keep(counts, "contexts", (long) Iterations.asList(connection.getContextIDs()).size());
			}
			return Boolean.TRUE;
		}, countBudgetMillis);
		builder.start("size", "contexts");
		builder.link(List.of(INFO));
		if (finished.isEmpty()) {
			BrowseList.countsTimedOut(builder);
		}
		builder.result(count(counts.get("size")), count(counts.get("contexts")));
		builder.end();
	}

	private static Value count(Long count) {
		return count == null ? null : SimpleValueFactory.getInstance().createLiteral(BigInteger.valueOf(count));
	}

	private String getServer() {
		String result = null; // gracefully ignored by builder.result(...)
		if (manager instanceof LocalRepositoryManager) {
			result = ((LocalRepositoryManager) manager).getBaseDir().toString();
		} else if (manager instanceof RemoteRepositoryManager) {
			result = ((RemoteRepositoryManager) manager).getServerURL();
		}
		return result;
	}

	@Override
	public void destroy() {
		browseList.shutdown();
		super.destroy();
	}

	private String getEffectiveConfigTurtle() {
		if (manager == null || info == null || info.getId() == null) {
			return null;
		}

		try {
			RepositoryConfig repositoryConfig = manager.getRepositoryConfig(info.getId());
			if (repositoryConfig == null) {
				return null;
			}

			Model model = new LinkedHashModel();
			repositoryConfig.export(model, bnode());

			WriterConfig writerConfig = new WriterConfig();
			writerConfig.set(BasicWriterSettings.PRETTY_PRINT, true);
			writerConfig.set(BasicWriterSettings.INLINE_BLANK_NODES, true);

			StringWriter writer = new StringWriter();
			Rio.write(model, writer, RDFFormat.TURTLE, writerConfig);
			return writer.toString();
		} catch (RepositoryConfigException | RepositoryException e) {
			LOGGER.warn("Unable to render effective repository config.", e);
			return null;
		}
	}
}
